import{_ as e,o as d,c as o,ag as c}from"./chunks/framework.Pp2klvcf.js";const b=JSON.parse('{"title":"内容与门户接口","description":"","frontmatter":{},"headers":[],"relativePath":"zh/server/api/content-portal.md","filePath":"zh/server/api/content-portal.md","lastUpdated":1788681727000}'),a={name:"zh/server/api/content-portal.md"};function r(i,t,l,n,p,s){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="内容与门户接口" tabindex="-1">内容与门户接口 <a class="header-anchor" href="#内容与门户接口" aria-label="Permalink to &quot;内容与门户接口&quot;">​</a></h1><h2 id="内容管理" tabindex="-1">内容管理 <a class="header-anchor" href="#内容管理" aria-label="Permalink to &quot;内容管理&quot;">​</a></h2><p>文章与分类提供完整 REST CRUD：</p><ul><li><code>/api/v1/content/articles</code></li><li><code>/api/v1/content/articles/{id}</code></li><li><code>/api/v1/content/categories</code></li><li><code>/api/v1/content/categories/{id}</code></li></ul><p>文章列表支持 <code>page</code>、<code>pageSize</code>、<code>keyword</code>、<code>categoryId</code> 和 <code>status</code>。内容字段为字符串数组，便于不同 UI 编辑器以段落形式呈现。</p><h2 id="门户公开数据" tabindex="-1">门户公开数据 <a class="header-anchor" href="#门户公开数据" aria-label="Permalink to &quot;门户公开数据&quot;">​</a></h2><p><code>/api/v1/public/**</code> 无需登录：</p><table tabindex="0"><thead><tr><th>路径</th><th>用途</th></tr></thead><tbody><tr><td><code>/blog</code>、<code>/blog/{id}</code></td><td>博客分页与详情</td></tr><tr><td><code>/home</code></td><td>首页统计、高亮与评价</td></tr><tr><td><code>/features</code>、<code>/product</code></td><td>产品能力</td></tr><tr><td><code>/pricing</code></td><td>套餐方案</td></tr><tr><td><code>/faq</code>、<code>/docs</code></td><td>帮助内容</td></tr><tr><td><code>/about</code></td><td>团队与里程碑</td></tr><tr><td><code>/contact</code></td><td>联系表单提交（POST）</td></tr></tbody></table><p>博客评论读取 <code>GET /api/v1/public/blog/{id}/comments</code> 也允许匿名访问。</p><h2 id="需要登录的站点交互" tabindex="-1">需要登录的站点交互 <a class="header-anchor" href="#需要登录的站点交互" aria-label="Permalink to &quot;需要登录的站点交互&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法与路径</th><th>用途</th></tr></thead><tbody><tr><td>POST <code>/api/v1/blog/{id}/comments</code></td><td>以当前登录用户身份发表评论</td></tr><tr><td>POST <code>/api/v1/payments/checkout</code></td><td>为付费套餐创建待支付订单</td></tr></tbody></table><p>匿名写入返回 HTTP 401。支付接口接收 <code>planId</code> 与 <code>channel</code>（<code>alipay</code>、<code>wechat</code> 或 <code>card</code>），返回订单号、金额、过期时间与演示支付地址。评论和订单由 <code>V7__site_interactions.sql</code> 创建的数据表持久化。</p><p>公开只代表无需身份，不代表允许任意写入。价格页和博客页本身保持公开，只有点击购买或提交评论时才跳转登录，登录后按 <code>redirect</code> 参数返回原页面。</p>',13)])])}const _=e(a,[["render",r]]);export{b as __pageData,_ as default};
